const express = require('express');
const http = require('http');
const path = require('path');
const fs = require('fs-extra');
const multer = require('multer');
const { Server } = require('socket.io');
const { v4: uuidv4 } = require('uuid');
const cors = require('cors');

const buildApk = require('./utils/buildApk');
const webScraper = require('./utils/webScraper');
const zipHandler = require('./utils/zipHandler');

const app = express();
const server = http.createServer(app);
const io = new Server(server, { cors: { origin: '*' } });

const PORT = process.env.PORT || 3000;
// On cloud platforms (Render, Railway) use /tmp — always writable.
// Locally fall back to the project folder.
const TMP_BASE = process.env.TMPDIR || process.env.TEMP || require('os').tmpdir();
const IS_CLOUD = !!process.env.RENDER || !!process.env.RAILWAY_ENVIRONMENT;
const UPLOADS_DIR = IS_CLOUD ? path.join(TMP_BASE, 'apkbuilder-uploads') : path.join(__dirname, 'uploads');
const BUILDS_DIR  = IS_CLOUD ? path.join(TMP_BASE, 'apkbuilder-builds')  : path.join(__dirname, 'builds');

fs.ensureDirSync(UPLOADS_DIR);
fs.ensureDirSync(BUILDS_DIR);

// In-memory build registry
const builds = {};

// ─── Multer ────────────────────────────────────────────────────────────────
const storage = multer.diskStorage({
  destination: UPLOADS_DIR,
  filename: (req, file, cb) => cb(null, `${uuidv4()}-${file.originalname}`)
});

const upload = multer({
  storage,
  limits: { fileSize: 200 * 1024 * 1024 }, // 200 MB
  fileFilter: (req, file, cb) => {
    const allowed = ['.zip', '.png', '.jpg', '.jpeg', '.svg', '.gif'];
    const ext = path.extname(file.originalname).toLowerCase();
    if (allowed.includes(ext)) return cb(null, true);
    cb(new Error(`File type ${ext} is not allowed`));
  }
});

// ─── Middleware ─────────────────────────────────────────────────────────────
app.use(cors());
app.use(express.json({ limit: '1mb' }));
app.use(express.static(path.join(__dirname, 'public')));
app.use('/builds', express.static(BUILDS_DIR));

// ─── Socket.io ──────────────────────────────────────────────────────────────
io.on('connection', (socket) => {
  console.log('Client connected:', socket.id);
});

function sendProgress(buildId, message, progress = null) {
  const data = { buildId, message, timestamp: new Date().toISOString() };
  if (progress !== null) data.progress = progress;
  io.emit(`build:${buildId}`, data);
  if (builds[buildId]) {
    builds[buildId].log.push(message);
    if (progress !== null) builds[buildId].progress = progress;
  }
}

// ─── Helpers ────────────────────────────────────────────────────────────────
function parseConfig(body) {
  return {
    appName: (body.appName || 'My App').substring(0, 50),
    packageName: sanitizePackageName(body.packageName || 'com.example.myapp'),
    versionName: body.versionName || '1.0.0',
    versionCode: Math.max(1, parseInt(body.versionCode) || 1),
    minSdk: parseInt(body.minSdk) || 21,
    orientation: ['unspecified', 'portrait', 'landscape'].includes(body.orientation)
      ? body.orientation : 'unspecified',
    enableZoom: body.enableZoom !== 'false' && body.enableZoom !== false,
    fullscreen: body.fullscreen === 'true' || body.fullscreen === true,
    allowExternalLinks: body.allowExternalLinks === 'true' || body.allowExternalLinks === true,
    statusBarColor: /^#[0-9A-Fa-f]{6}$/.test(body.statusBarColor) ? body.statusBarColor : '#000000',
  };
}

function sanitizePackageName(name) {
  // Enforce valid Java package name
  const clean = name.replace(/[^a-zA-Z0-9_.]/g, '_').replace(/^[^a-zA-Z]/, 'p');
  const parts = clean.split('.');
  // Ensure at least 2 parts, each starting with letter
  const valid = parts
    .filter(p => p.length > 0)
    .map(p => /^[a-zA-Z]/.test(p) ? p : `p${p}`);
  if (valid.length < 2) valid.push('app');
  return valid.join('.');
}

async function findIndexHtml(dir) {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name === 'index.html') return path.join(dir, entry.name);
  }
  for (const entry of entries) {
    if (entry.isDirectory()) {
      const found = await findIndexHtml(path.join(dir, entry.name));
      if (found) return found;
    }
  }
  return null;
}

// ─── Routes ──────────────────────────────────────────────────────────────────

// Build from URL
app.post('/api/build-from-url', async (req, res) => {
  const { url, offline } = req.body;
  if (!url || !url.startsWith('http')) {
    return res.status(400).json({ error: 'A valid http/https URL is required' });
  }

  const buildId = uuidv4();
  builds[buildId] = { id: buildId, status: 'running', progress: 0, log: [], type: 'url' };
  res.json({ buildId });

  setImmediate(async () => {
    try {
      const config = parseConfig(req.body);
      sendProgress(buildId, `🌐 Starting build for: ${url}`, 5);

      let webDir = null;
      if (offline) {
        sendProgress(buildId, '⬇️  Downloading website for offline packaging…', 10);
        webDir = await webScraper.downloadSite(url, buildId,
          (msg) => sendProgress(buildId, msg));
        config.loadType = 'local';
      } else {
        config.loadType = 'url';
        config.loadUrl = url;
        sendProgress(buildId, '🔗 Configuring WebView to load URL at runtime…', 20);
      }

      sendProgress(buildId, '📁 Creating Android project structure…', 35);
      const projectDir = await buildApk.createProject(buildId, config, webDir, BUILDS_DIR);

      sendProgress(buildId, '🔨 Attempting Gradle build…', 50);
      const result = await buildApk.build(projectDir, buildId,
        (msg) => sendProgress(buildId, msg), BUILDS_DIR);

      if (webDir) fs.remove(webDir).catch(() => {});

      emitComplete(buildId, result);
    } catch (err) {
      emitError(buildId, err);
    }
  });
});

// Build from ZIP
app.post('/api/build-from-zip',
  upload.fields([{ name: 'zipFile', maxCount: 1 }, { name: 'appIcon', maxCount: 1 }]),
  async (req, res) => {
    if (!req.files?.zipFile) {
      return res.status(400).json({ error: 'A ZIP file is required' });
    }

    const buildId = uuidv4();
    builds[buildId] = { id: buildId, status: 'running', progress: 0, log: [], type: 'zip' };
    res.json({ buildId });

    const zipPath = req.files.zipFile[0].path;
    const iconPath = req.files?.appIcon?.[0]?.path || null;

    setImmediate(async () => {
      try {
        const config = parseConfig(req.body);
        config.loadType = 'local';
        if (iconPath) config.iconFilePath = iconPath;

        sendProgress(buildId, '📦 Extracting ZIP file…', 10);
        const webDir = await zipHandler.extract(zipPath, buildId);

        const indexHtml = await findIndexHtml(webDir);
        if (!indexHtml) {
          throw new Error('No index.html found in the ZIP. Ensure your web app has index.html at the root or in a subfolder.');
        }
        const relDir = path.relative(webDir, path.dirname(indexHtml));
        if (relDir) {
          sendProgress(buildId, `📂 Found index.html in subfolder: ${relDir}`, 20);
          config.indexSubDir = relDir;
        }

        sendProgress(buildId, '📁 Creating Android project structure…', 35);
        const projectDir = await buildApk.createProject(buildId, config, webDir, BUILDS_DIR);

        sendProgress(buildId, '🔨 Attempting Gradle build…', 50);
        const result = await buildApk.build(projectDir, buildId,
          (msg) => sendProgress(buildId, msg), BUILDS_DIR);

        fs.remove(zipPath).catch(() => {});
        fs.remove(webDir).catch(() => {});
        if (iconPath) fs.remove(iconPath).catch(() => {});

        emitComplete(buildId, result);
      } catch (err) {
        fs.remove(zipPath).catch(() => {});
        if (iconPath) fs.remove(iconPath).catch(() => {});
        emitError(buildId, err);
      }
    });
  }
);

function emitComplete(buildId, result) {
  if (result.apkPath) {
    builds[buildId].status = 'success';
    sendProgress(buildId, '✅ APK built successfully!', 100);
    io.emit(`build:${buildId}:complete`, {
      buildId,
      apkUrl: `/builds/${buildId}/${path.basename(result.apkPath)}`,
      projectUrl: `/builds/${buildId}/project.zip`,
      hasApk: true
    });
  } else {
    builds[buildId].status = 'partial';
    sendProgress(buildId, '📦 Project ZIP is ready. Open in Android Studio to build the APK.', 100);
    io.emit(`build:${buildId}:complete`, {
      buildId,
      projectUrl: `/builds/${buildId}/project.zip`,
      hasApk: false
    });
  }
}

function emitError(buildId, err) {
  console.error('Build error:', err);
  builds[buildId].status = 'error';
  builds[buildId].error = err.message;
  sendProgress(buildId, `❌ Error: ${err.message}`);
  io.emit(`build:${buildId}:error`, { buildId, error: err.message });
}

// Status endpoint
app.get('/api/status/:id', (req, res) => {
  const build = builds[req.params.id];
  if (!build) return res.status(404).json({ error: 'Build not found' });
  res.json(build);
});

// List builds
app.get('/api/builds', (req, res) => {
  res.json(Object.values(builds).map(b => ({
    id: b.id, status: b.status, progress: b.progress, type: b.type
  })));
});

server.listen(PORT, () => {
  console.log(`\n🚀 APK Builder is running → http://localhost:${PORT}\n`);
});
